import pandas as pd,numpy as np,warnings
from sklearn.model_selection import GroupKFold
from sklearn.ensemble import ExtraTreesRegressor,RandomForestRegressor
from sklearn.metrics import mean_absolute_error
from catboost import CatBoostRegressor
warnings.filterwarnings('ignore')
tr=pd.read_csv('b3_htsteel_process_train.csv'); po=pd.read_csv('b3_htsteel_process_pool.csv'); X=tr.drop(columns='target'); y=tr.target.to_numpy(); P=po.drop(columns='candidate_id'); comp=X.columns[:16]
groups=pd.factorize(pd.MultiIndex.from_frame(X[comp]))[0]
scale=np.maximum(X[comp].std().to_numpy(),1e-12); pc=P[comp].drop_duplicates().to_numpy(); d=np.sqrt(np.min(np.mean(((X[comp].to_numpy()[:,None,:]-pc[None,:,:])/scale)**2,axis=2),axis=1)); q=np.exp(-(d/.5)**2)+.03
sp=list(GroupKFold(5,shuffle=True,random_state=42).split(X,y,groups))
for fam in ['ET','RF','CB']:
 for weighted in [False,True]:
  vals=[]
  for k,(a,b) in enumerate(sp):
   if fam=='ET':m=ExtraTreesRegressor(n_estimators=600,max_features=.8,n_jobs=-1,random_state=17+k)
   elif fam=='RF':m=RandomForestRegressor(n_estimators=600,max_features=.8,n_jobs=-1,random_state=17+k)
   else:m=CatBoostRegressor(iterations=600,depth=5,learning_rate=.03,verbose=False,random_seed=17+k,allow_writing_files=False)
   kw={'sample_weight':q[a]} if weighted else {}
   m.fit(X.iloc[a],y[a],**kw); p=m.predict(X.iloc[b]); vals.append(mean_absolute_error(y[b],p,sample_weight=q[b]))
  print(fam,'weighted' if weighted else 'global','query-weighted group MAE',round(np.mean(vals),1))
PY

